// One post. Generated by SearchBlueprint — safe to edit, it is your file now.
import { createFileRoute, Link } from "@tanstack/react-router";
import { getPostBySlug } from "../lib/blog/posts";
import { blogStyles } from "../lib/blog/styles";

export const Route = createFileRoute("/blog/$slug")({
  component: BlogPostPage,
  head: ({ params }: { params: { slug: string } }) => {
    const post = getPostBySlug(params.slug);
    if (!post) return {};
    const url = "/blog/" + post.slug;
    return {
      meta: [
        { title: post.title },
        { name: "description", content: post.description },
        { property: "og:type", content: "article" },
        { property: "og:title", content: post.title },
        { property: "og:description", content: post.description },
        { name: "twitter:card", content: "summary_large_image" },
      ],
      links: [{ rel: "canonical", href: url }],
    };
  },
});

function BlogPostPage() {
  const { slug } = Route.useParams();
  const post = getPostBySlug(slug);
  if (!post) {
    return (
      <div>
        <style>{blogStyles}</style>
        <div className="sb-blog">
          <h1>Post not found</h1>
          <p className="sb-blog-empty">That article does not exist, or it has been removed.</p>
          <Link className="sb-blog-back" to="/blog">
            Back to all posts
          </Link>
        </div>
      </div>
    );
  }
  const jsonLd: Record<string, string> = {
    "@context": "https://schema.org",
    "@type": "BlogPosting",
    headline: post.title,
  };
  if (post.description) jsonLd.description = post.description;
  if (post.date) {
    jsonLd.datePublished = post.date;
    jsonLd.dateModified = post.date;
  }
  return (
    <div>
      <style>{blogStyles}</style>
      <article className="sb-blog">
        <script type="application/ld+json" dangerouslySetInnerHTML={{ __html: JSON.stringify(jsonLd).replace(/</g, "\\u003c") }} />
        <h1>{post.title}</h1>
        {post.dateLabel ? (
          <time className="sb-blog-meta" dateTime={post.date}>
            {post.dateLabel}
          </time>
        ) : null}
        <div className="sb-blog-body" dangerouslySetInnerHTML={{ __html: post.html }} />
        <Link className="sb-blog-back" to="/blog">
          Back to all posts
        </Link>
      </article>
    </div>
  );
}
